// SPDX-License-Identifier: LicenseRef-Degensoft-SwapVM-1.1
pragma solidity ^0.8.30;

/// @custom:license-url https://github.com/1inch/swap-vm/blob/main/LICENSES/SwapVM-1.1.txt
/// @custom:copyright © 2025 Degensoft Ltd

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

import { Calldata } from "@1inch/solidity-utils/contracts/libraries/Calldata.sol";
import { Power } from "../libs/Power.sol";
import { Context, ContextLib } from "../libs/VM.sol";

library DutchAuctionArgsBuilder {
    using Calldata for bytes;

    error DutchAuctionDecayFactorShouldBeLessThanOneE18(uint168 decayFactor);
    error DutchAuctionMissingStartTime();
    error DutchAuctionMissingDuration();
    error DutchAuctionMissingDecayFactor();

    /// @notice Build instruction arguments for DutchAuction
    /// @param startTime Auction start timestamp (seconds)
    /// @param duration Auction duration (seconds) - auction expires at startTime + duration
    /// @param decayFactor Price decay per second (< 1e18), e.g., 0.99e18 = 1% decay/sec
    /// @return Packed bytes for inclusion in program bytecode (15 bytes total)
    function build(
        uint40 startTime,
        uint16 duration,
        uint64 decayFactor
    ) internal pure returns (bytes memory) {
        require(decayFactor < 1e18, DutchAuctionDecayFactorShouldBeLessThanOneE18(decayFactor));
        return abi.encodePacked(
            startTime,
            duration,
            decayFactor
        );
    }

    function parse(bytes calldata args) internal pure returns (
        uint40 startTime,
        uint16 duration,
        uint64 decayFactor
    ) {
        startTime = uint40(bytes5(args.slice(0, 5, DutchAuctionMissingStartTime.selector)));
        duration = uint16(bytes2(args.slice(5, 7, DutchAuctionMissingDuration.selector)));
        decayFactor = uint64(bytes8(args.slice(7, 15, DutchAuctionMissingDecayFactor.selector)));
    }
}

/**
 * @notice Dutch Auction instruction for time-based price decay with deadline
 * @dev Implements an exponential decay auction mechanism that works after any swap:
 * - Designed to be used after any swap instruction (LimitSwap, XYCSwap, etc.) which sets amounts
 * - Applies time-based decay to the amounts calculated by the previous swap
 * - Maker sells token0 and receives token1
 * - Price improves for taker over time through exponential decay until deadline
 * - Reverts if current time exceeds deadline
 * - Only works for 1=>0 swaps (token1 to token0)
 *
 * The decay factor determines the price reduction rate:
 * - 1.0e18 = no decay (constant price)
 * - 0.999e18 = 0.1% decay per second
 * - 0.99e18 = 1% decay per second
 * - 0.9e18 = 10% decay per second
 *
 * Example usage:
 * 1. Any swap instruction sets: 100 token1 → 1000 token0
 * 2. DutchAuction with decayFactor = 0.99e18, after 100 seconds:
 *    - exactIn: Taker gets ~2.73x more token0 for the same token1
 *    - exactOut: Taker needs only ~36.6% of initial token1
 * 3. After deadline, the auction expires and cannot be executed
 */
contract DutchAuction {
    using ContextLib for Context;
    using Math for uint256;
    using Power for uint256;

    error DutchAuctionShouldBeAppliedBeforeSwapAmountsComputed(uint256 amountIn, uint256 amountOut);
    error DutchAuctionExpired(uint256 currentTime, uint256 deadline);

    /// @notice Apply Dutch auction decay to shrink the amount in by shrinking the balance in
    function _dutchAuctionBalanceIn1D(Context memory ctx, bytes calldata args) internal view {
        require(ctx.swap.amountIn == 0 || ctx.swap.amountOut == 0, DutchAuctionShouldBeAppliedBeforeSwapAmountsComputed(ctx.swap.amountIn, ctx.swap.amountOut));

        (uint256 startTime, uint256 duration, uint256 decayFactor) = DutchAuctionArgsBuilder.parse(args);
        require(block.timestamp <= startTime + duration, DutchAuctionExpired(block.timestamp, startTime + duration));
        uint256 elapsed = block.timestamp - startTime;
        uint256 decay = decayFactor.pow(elapsed, 1e18);
        ctx.swap.balanceIn = ctx.swap.balanceIn * decay / 1e18;
    }

    /// @notice Apply Dutch auction decay to increase the amount out by increasing the balance out
    function _dutchAuctionBalanceOut1D(Context memory ctx, bytes calldata args) internal view {
        require(ctx.swap.amountIn == 0 || ctx.swap.amountOut == 0, DutchAuctionShouldBeAppliedBeforeSwapAmountsComputed(ctx.swap.amountIn, ctx.swap.amountOut));

        (uint256 startTime, uint256 duration, uint256 decayFactor) = DutchAuctionArgsBuilder.parse(args);
        require(block.timestamp <= startTime + duration, DutchAuctionExpired(block.timestamp, startTime + duration));
        uint256 elapsed = block.timestamp - startTime;
        uint256 decay = decayFactor.pow(elapsed, 1e18);
        ctx.swap.balanceOut = ctx.swap.balanceOut * 1e18 / decay;
    }
}

project/src/instructions/Extruction.sol.content:
// SPDX-License-Identifier: LicenseRef-Degensoft-SwapVM-1.1
pragma solidity ^0.8.30;

/// @custom:license-url https://github.com/1inch/swap-vm/blob/main/LICENSES/SwapVM-1.1.txt
/// @custom:copyright © 2025 Degensoft Ltd

import { Calldata } from "@1inch/solidity-utils/contracts/libraries/Calldata.sol";
import { Context, ContextLib, SwapQuery, SwapRegisters } from "../libs/VM.sol";

/// @title IExtruction - State-modifying external logic interface
/// @notice Interface for external contracts that implement custom swap logic during swap() execution
/// @dev CRITICAL SECURITY REQUIREMENTS:
///      - Implementations MUST produce deterministic and consistent results with IStaticExtruction
///      - The same inputs MUST yield the same swap amounts in both interfaces
///      - Non-deterministic behavior will cause quote/swap inconsistencies and unexpected execution
///      - Target contracts SHOULD be immutable (non-upgradeable) to prevent logic changes between quote/swap
interface IExtruction {
    function extruction(
        bool isStaticContext,
        uint256 nextPC,
        SwapQuery calldata query,
        SwapRegisters calldata swap,
        bytes calldata args,
        bytes calldata takerData
    ) external returns (
        uint256 updatedNextPC,
        uint256 choppedLength,
        SwapRegisters memory updatedSwap
    );
}

/// @title IStaticExtruction - View-only external logic interface
/// @notice Interface for external contracts that implement custom swap logic during quote() execution
/// @dev CRITICAL SECURITY REQUIREMENTS:
///      - Implementations MUST be deterministic and consistent with IExtruction
///      - The same inputs MUST yield the same swap amounts in both interfaces
///      - This is the read-only version called during quoting operations
///      - Inconsistent implementations will break quote/swap consistency guarantees
interface IStaticExtruction {
    function extruction(
        bool isStaticContext,
        uint256 nextPC,
        SwapQuery calldata query,
        SwapRegisters calldata swap,
        bytes calldata args,
        bytes calldata takerData
    ) external view returns (
        uint256 updatedNextPC,
        uint256 choppedLength,
        SwapRegisters memory updatedSwap
    );
}

/// @title Extruction - External Custom Logic Delegation
/// @notice Allows makers to delegate pricing and state logic to external contracts for advanced strategies
/// @dev IMPORTANT SECURITY CONSIDERATIONS FOR TAKERS/RESOLVERS:
///
///      Quote/Swap Consistency Risk:
///      - This instruction delegates logic to maker-controlled external contracts
///      - Takers MUST validate strategy consistency before execution
///      - IStaticExtruction.extruction() (quote) and IExtruction.extruction() (swap) MUST return
///        consistent results for the same inputs
///
///      Validation Requirements:
///      - Verify target contract is non-upgradeable or has trusted governance
///      - Ensure target implementation is deterministic and cannot change between quote/swap
///      - Review target contract code for correctness and security
///      - Test quote/swap consistency before routing significant volume
///
///      Risk Mitigation:
///      - Takers already have slippage protection via threshold amounts
///      - Consider using additional monitoring for Extruction-based strategies
///      - Only interact with strategies that have been thoroughly validated
///
///      This is a "use at your own risk" feature designed for advanced use cases.
///      Failure to validate may result in quote/swap inconsistencies, reverts, or unexpected execution.
contract Extruction {
    using Calldata for bytes;
    using ContextLib for Context;

    error ExtructionMissingTargetArg();
    error ExtructionChoppedExceededLength(bytes chopped, uint256 requested);

    /// @dev Calls an external contract to perform custom logic, potentially modifying the swap state
    /// @dev QUOTE/SWAP DIVERGENCE: This instruction delegates to external contracts (IStaticExtruction for
    ///   quote, IExtruction for swap). Target implementations MUST be deterministic and return consistent
    ///   results in both modes. Non-deterministic behavior breaks numerical consistency. Makers MUST NOT
    ///   use backward jumps to this instruction as it breaks consistency between quote() and swap().
    /// @param args.target         | 20 bytes
    /// @param args.extructionArgs | N bytes
    function _extruction(Context memory ctx, bytes calldata args) internal {
        address target = address(bytes20(args.slice(0, 20, ExtructionMissingTargetArg.selector)));
        uint256 choppedLength;

        if (ctx.vm.isStaticContext) {
            (ctx.vm.nextPC, choppedLength, ctx.swap) = IStaticExtruction(target).extruction(
                ctx.vm.isStaticContext,
                ctx.vm.nextPC,
                ctx.query,
                ctx.swap,
                args.slice(20),
                ctx.takerArgs()
            );
        } else {
            (ctx.vm.nextPC, choppedLength, ctx.swap) = IExtruction(target).extruction(
                ctx.vm.isStaticContext,
                ctx.vm.nextPC,
                ctx.query,
                ctx.swap,
                args.slice(20),
                ctx.takerArgs()
            );
        }
        bytes calldata chopped = ctx.tryChopTakerArgs(choppedLength);
        require(chopped.length == choppedLength, ExtructionChoppedExceededLength(chopped, choppedLength)); // Revert if not enough data
    }
}

project/src/instructions/Fee.sol.content:
// SPDX-License-Identifier: LicenseRef-Degensoft-SwapVM-1.1
pragma solidity ^0.8.30;

/// @custom:license-url https://github.com/1inch/swap-vm/blob/main/LICENSES/SwapVM-1.1.txt
/// @custom:copyright © 2025 Degensoft Ltd

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@1inch/solidity-utils/contracts/libraries/SafeERC20.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IAqua } from "@1inch/aqua/src/interfaces/IAqua.sol";

import { IProtocolFeeProvider } from "./interfaces/IProtocolFeeProvider.sol";

import { Calldata } from "@1inch/solidity-utils/contracts/libraries/Calldata.sol";
import { Context, ContextLib } from "../libs/VM.sol";

uint256 constant BPS = 1e9;

library FeeArgsBuilder {
    using Calldata for bytes;

    error FeeBpsOutOfRange(uint32 feeBps);
    error FeeMissingFeeBPS();
    error ProtocolFeeMissingFeeBPS();
    error ProtocolFeeMissingTo();
    error ProtocolFeeProviderMissingAddress();

    function buildFlatFee(uint32 feeBps) internal pure returns (bytes memory) {
        require(feeBps <= BPS, FeeBpsOutOfRange(feeBps));
        return abi.encodePacked(feeBps);
    }

    function buildProtocolFee(uint32 feeBps, address to) internal pure returns (bytes memory) {
        require(feeBps <= BPS, FeeBpsOutOfRange(feeBps));
        return abi.encodePacked(feeBps, to);
    }

    function buildDynamicProtocolFee(address feeProvider) internal pure returns (bytes memory) {
        return abi.encodePacked(feeProvider);
    }

    function parseFlatFee(bytes calldata args) internal pure returns (uint32 feeBps) {
        feeBps = uint32(bytes4(args.slice(0, 4, FeeMissingFeeBPS.selector)));
    }

    function parseProtocolFee(bytes calldata args) internal pure returns (uint32 feeBps, address to) {
        feeBps = uint32(bytes4(args.slice(0, 4, ProtocolFeeMissingFeeBPS.selector)));
        to = address(uint160(bytes20(args.slice(4, 24, ProtocolFeeMissingTo.selector))));
    }

    function parseDynamicProtocolFee(bytes calldata args) internal pure returns (address feeProvider) {
        feeProvider = address(uint160(bytes20(args.slice(0, 20, ProtocolFeeProviderMissingAddress.selector))));
    }
}

contract Fee {
    using SafeERC20 for IERC20;
    using ContextLib for Context;

    error FeeShouldBeAppliedBeforeSwapAmountsComputation();
    error FeeDynamicProtocolInvalidRecipient();
    error FeeBpsOutOfRange(uint256 feeBps);
    error FeeProtocolProviderFailedCall();

    IAqua internal immutable _AQUA;

    constructor(address aqua) {
        _AQUA = IAqua(aqua);
    }

    /// @param args.feeBps | 4 bytes (fee in bps, 1e9 = 100%)
    function _flatFeeAmountInXD(Context memory ctx, bytes calldata args) internal {
        uint256 feeBps = FeeArgsBuilder.parseFlatFee(args);
        require(ctx.swap.amountIn == 0 || ctx.swap.amountOut == 0, FeeShouldBeAppliedBeforeSwapAmountsComputation());

        // This is the same _feeAmountIn call, just with rounding up.
        if (ctx.query.isExactIn) {
            // Decrease amountIn by fee only during swap-instruction
            uint256 takerDefinedAmountIn = ctx.swap.amountIn;
            ctx.swap.amountIn -= Math.ceilDiv(ctx.swap.amountIn * feeBps, BPS);
            ctx.runLoop();
            ctx.swap.amountIn = takerDefinedAmountIn;
        } else {
            // Increase amountIn by fee after swap-instruction
            ctx.runLoop();
            ctx.swap.amountIn += Math.ceilDiv(ctx.swap.amountIn * feeBps, BPS - feeBps);
        }
    }

    /// @notice Protocol fee on amountIn — transfers fee from maker to recipient via safeTransferFrom.
    /// @dev IMPORTANT: The maker MUST already hold sufficient tokenIn balance and have approved this contract
    ///   BEFORE the swap is executed. The fee transfer occurs during program execution (inside runLoop),
    ///   which is before SwapVM completes the taker→maker tokenIn transfer. If the maker lacks tokenIn
    ///   balance or allowance, the swap will revert.
    /// @dev QUOTE/SWAP DIVERGENCE: In quote mode (isStaticContext=true), this instruction computes the fee
    ///   but skips the actual token transfer. Quote may succeed while swap reverts due to insufficient
    ///   balance or missing approval. Makers MUST NOT use backward jumps to this instruction as it may
    ///   break numerical consistency between quote() and swap().
    /// @param args.feeBps | 4 bytes (fee in bps, 1e9 = 100%)
    /// @param args.to     | 20 bytes (address to send pulled tokens to)
    function _protocolFeeAmountInXD(Context memory ctx, bytes calldata args) internal {
        (uint256 feeBps, address to) = FeeArgsBuilder.parseProtocolFee(args);
        uint256 feeAmountIn = _feeAmountIn(ctx, feeBps);

        if (!ctx.vm.isStaticContext) {
            IERC20(ctx.query.tokenIn).safeTransferFrom(ctx.query.maker, to, feeAmountIn);
        }
    }

    /// @notice Protocol fee on amountIn for Aqua — pulls fee from maker's Aqua balance to recipient.
    /// @dev IMPORTANT: The maker MUST already hold sufficient tokenIn balance in Aqua BEFORE the swap
    ///   is executed. The fee pull occurs during program execution (inside runLoop), which is before
    ///   SwapVM completes the taker→maker tokenIn transfer. If the maker's Aqua tokenIn balance is
    ///   insufficient, the swap will revert.
    /// @dev QUOTE/SWAP DIVERGENCE: In quote mode (isStaticContext=true), this instruction computes the fee
    ///   but skips the Aqua pull operation. Quote may succeed while swap reverts due to insufficient
    ///   Aqua balance. Makers MUST NOT use backward jumps to this instruction as it may break numerical
    ///   consistency between quote() and swap().
    /// @param args.feeBps | 4 bytes (fee in bps, 1e9 = 100%)
    /// @param args.to     | 20 bytes (address to send pulled tokens to)
    function _aquaProtocolFeeAmountInXD(Context memory ctx, bytes calldata args) internal {
        (uint256 feeBps, address to) = FeeArgsBuilder.parseProtocolFee(args);
        uint256 feeAmountIn = _feeAmountIn(ctx, feeBps);
        ctx.swap.amountNetPulled += feeAmountIn;

        if (!ctx.vm.isStaticContext) {
            _AQUA.pull(ctx.query.maker, ctx.query.orderHash, ctx.query.tokenIn, feeAmountIn, to);
        }
    }

    /// @notice Dynamic protocol fee with external fee provider
    /// @dev IMPORTANT: The maker MUST already hold sufficient tokenIn balance and have approved this contract
    ///   BEFORE the swap is executed. The fee transfer occurs during program execution (inside runLoop),
    ///   which is before SwapVM completes the taker→maker tokenIn transfer. If the maker lacks tokenIn
    ///   balance or allowance, the swap will revert.
    /// @dev QUOTE/SWAP DIVERGENCE: In quote mode (isStaticContext=true), this instruction computes the fee
    ///   but skips the actual token transfer. Quote may succeed while swap reverts due to insufficient
    ///   balance or missing approval. Makers MUST NOT use backward jumps to this instruction as it may
    ///   break numerical consistency between quote() and swap().
    /// @dev REENTRANCY SAFETY:
    ///   - Uses staticcall preventing state changes by feeProvider
    ///   - Protected by TransientLock on orderHash level in SwapVM.swap()
    ///   - Fee calculation and state changes happen AFTER external call
    ///   - feeProvider MUST NOT rely on intermediate swap state
    ///   CAUTION: Takers should verify feeProvider trustworthiness before executing.
    ///      A malicious feeProvider could return large data causing high gas consumption.
    /// @param args.feeProvider | 20 bytes (address of the protocol fee provider)
    function _dynamicProtocolFeeAmountInXD(Context memory ctx, bytes calldata args) internal {
        address feeProvider = FeeArgsBuilder.parseDynamicProtocolFee(args);
        uint256 feeBps;
        address to;

        if (feeProvider != address(0)) {
            (bool success, bytes memory result) = feeProvider.staticcall(abi.encodeCall(
                IProtocolFeeProvider.getFeeBpsAndRecipient,
                (ctx.query.orderHash,
                ctx.query.maker,
                ctx.query.taker,
                ctx.query.tokenIn,
                ctx.query.tokenOut,
                ctx.query.isExactIn)
            ));

            require(success && result.length == 64, FeeProtocolProviderFailedCall());
            (feeBps, to) = abi.decode(result, (uint32, address));
            require(feeBps <= BPS, FeeBpsOutOfRange(feeBps));
        }

        if (feeBps != 0) {
            require(to != address(0), FeeDynamicProtocolInvalidRecipient());

            uint256 feeAmountIn = _feeAmountIn(ctx, feeBps);

            if (!ctx.vm.isStaticContext && feeAmountIn > 0) {
                IERC20(ctx.query.tokenIn).safeTransferFrom(ctx.query.maker, to, feeAmountIn);
            }
        }
    }

    /// @notice Dynamic protocol fee with external fee provider (Aqua version)
    /// @dev IMPORTANT: The maker MUST already hold sufficient tokenIn balance in Aqua BEFORE the swap
    ///   is executed. The fee pull occurs during program execution (inside runLoop), which is before
    ///   SwapVM completes the taker→maker tokenIn transfer. If the maker's Aqua tokenIn balance is
    ///   insufficient, the swap will revert.
    /// @dev QUOTE/SWAP DIVERGENCE: In quote mode (isStaticContext=true), this instruction computes the fee
    ///   but skips the Aqua pull operation. Quote may succeed while swap reverts due to insufficient
    ///   Aqua balance. Makers MUST NOT use backward jumps to this instruction as it may break numerical
    ///   consistency between quote() and swap().
    /// @dev REENTRANCY SAFETY:
    ///   - Uses staticcall preventing state changes by feeProvider
    ///   - Protected by TransientLock on orderHash level in SwapVM.swap()
    ///   - Fee calculation and state changes happen AFTER external call
    ///   - feeProvider MUST NOT rely on intermediate swap state
    ///   CAUTION: Takers should verify feeProvider trustworthiness before executing.
    ///      A malicious feeProvider could return large data causing high gas consumption.
    /// @param args.feeProvider | 20 bytes (address of the protocol fee provider)
    function _aquaDynamicProtocolFeeAmountInXD(Context memory ctx, bytes calldata args) internal {
        address feeProvider = FeeArgsBuilder.parseDynamicProtocolFee(args);
        uint256 feeBps;
        address to;

        if (feeProvider != address(0)) {
            (bool success, bytes memory result) = feeProvider.staticcall(abi.encodeCall(
                IProtocolFeeProvider.getFeeBpsAndRecipient,
                (ctx.query.orderHash,
                ctx.query.maker,
                ctx.query.taker,
                ctx.query.tokenIn,
                ctx.query.tokenOut,
                ctx.query.isExactIn)
            ));

            require(success && result.length == 64, FeeProtocolProviderFailedCall());
            (feeBps, to) = abi.decode(result, (uint32, address));
            require(feeBps <= BPS, FeeBpsOutOfRange(feeBps));
        }

        if (feeBps != 0) {
            require(to != address(0), FeeDynamicProtocolInvalidRecipient());

            uint256 feeAmountIn = _feeAmountIn(ctx, feeBps);
            ctx.swap.amountNetPulled += feeAmountIn;

            if (!ctx.vm.isStaticContext && feeAmountIn > 0) {
                _AQUA.pull(ctx.query.maker, ctx.query.orderHash, ctx.query.tokenIn, feeAmountIn, to);
            }
        }
    }

    // Internal functions

    function _feeAmountIn(Context memory ctx, uint256 feeBps) internal returns (uint256 feeAmountIn) {
        require(ctx.swap.amountIn == 0 || ctx.swap.amountOut == 0, FeeShouldBeAppliedBeforeSwapAmountsComputation());

        if (ctx.query.isExactIn) {
            // Decrease amountIn by fee only during swap-instruction
            uint256 takerDefinedAmountIn = ctx.swap.amountIn;
            feeAmountIn = ctx.swap.amountIn * feeBps / BPS;
            ctx.swap.amountIn -= feeAmountIn;
            ctx.runLoop();
            ctx.swap.amountIn = takerDefinedAmountIn;
        } else {
            // Increase amountIn by fee after swap-instruction
            ctx.runLoop();
            feeAmountIn = ctx.swap.amountIn * feeBps / (BPS - feeBps);
            ctx.swap.amountIn += feeAmountIn;
        }
    }
}

