// SPDX-License-Identifier: LicenseRef-Degensoft-SwapVM-1.1
pragma solidity ^0.8.30;

/// @custom:license-url https://github.com/1inch/swap-vm/blob/main/LICENSES/SwapVM-1.1.txt
/// @custom:copyright © 2025 Degensoft Ltd

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { AquaSwapVMTest } from "./base/AquaSwapVMTest.sol";

import { ISwapVM } from "../src/interfaces/ISwapVM.sol";
import { BPS } from "../src/instructions/Fee.sol";
import { ContextLib } from "../src/libs/VM.sol";
import { TakerTraitsLib } from "../src/libs/TakerTraits.sol";



contract FeeAquaTest is AquaSwapVMTest {
    function setUp() public virtual override {
        super.setUp();
    }

    function _makerSetup(
        uint32 feeInBps
    ) internal pure returns (MakerSetup memory) {
        return MakerSetup({
            balanceA: INITIAL_BALANCE_A,
            balanceB: INITIAL_BALANCE_B,
            priceMin: 0,
            priceMax: 0,
            protocolFeeBps: 0,
            feeInBps: feeInBps,
            protocolFeeRecipient: address(0),
            swapType: SwapType.XYC
        });
    }

    function _swapProgram(
        uint256 amount,
        bool zeroForOne,
        bool isExactIn
    ) internal view returns (SwapProgram memory) {
        return SwapProgram({
            amount: amount,
            taker: taker,
            tokenA: tokenA,
            tokenB: tokenB,
            zeroForOne: zeroForOne,
            isExactIn: isExactIn
        });
    }

    function test_Aqua_FeeIn_ExactIn_BalanceAfterSwap() public {
        MakerSetup memory setup = _makerSetup(0.10e9); // 10% fee in
        ISwapVM.Order memory order = createStrategy(setup);
        bytes32 strategyHash = shipStrategy(order, tokenA, tokenB, setup.balanceA, setup.balanceB);
        SwapProgram memory swapProgram = _swapProgram(100e18, true, true); // Swap 100 tokenA for tokenB

        (uint256 makerBalanceABefore, uint256 makerBalanceBBefore) = getAquaBalances(strategyHash);

        mintTokenInToTaker(swapProgram);
        (uint256 takerBalanceABefore, uint256 takerBalanceBBefore) = getTakerBalances(swapProgram.taker);

        mintTokenOutToMaker(swapProgram, 200e18);
        (uint256 amountIn, uint256 amountOut) = swap(swapProgram, order);

        (uint256 makerBalanceAAfter, uint256 makerBalanceBAfter) = getAquaBalances(strategyHash);
        (uint256 takerBalanceAAfter, uint256 takerBalanceBAfter) = getTakerBalances(swapProgram.taker);

        uint256 expectedFee = amountIn * setup.feeInBps / BPS;
        uint256 amountOutExpected = setup.balanceB * (amountIn - expectedFee) / (setup.balanceA + amountIn - expectedFee);
        assertEq(takerBalanceBAfter - takerBalanceBBefore, amountOutExpected, "Taker received correct amountOut");
        assertEq(makerBalanceAAfter, makerBalanceABefore + amountIn, "Maker balance A should increase by amountIn");
        assertEq(makerBalanceBAfter, makerBalanceBBefore - amountOut, "Maker balance B should decrease by amountOut");
        assertEq(takerBalanceAAfter, takerBalanceABefore - amountIn, "Taker balance A should decrease by amountIn");
        assertEq(takerBalanceBAfter, takerBalanceBBefore + amountOut, "Taker balance B should increase by amountOut");
    }

    function test_Aqua_FeeIn_ExactOut_BalancesAfterSwap() public {
        MakerSetup memory setup = _makerSetup(0.10e9); // 10% fee in
        ISwapVM.Order memory order = createStrategy(setup);
        bytes32 strategyHash = shipStrategy(order, tokenA, tokenB, setup.balanceA, setup.balanceB);
        SwapProgram memory swapProgram = _swapProgram(100e18, true, false); // Swap for 100 tokenB

        (uint256 makerBalanceABefore, uint256 makerBalanceBBefore) = getAquaBalances(strategyHash);

        mintTokenInToTaker(swapProgram);
        (uint256 takerBalanceABefore, uint256 takerBalanceBBefore) = getTakerBalances(swapProgram.taker);

        mintTokenOutToMaker(swapProgram, 200e18);
        (uint256 amountIn, uint256 amountOut) = swap(swapProgram, order);

        (uint256 makerBalanceAAfter, uint256 makerBalanceBAfter) = getAquaBalances(strategyHash);
        (uint256 takerBalanceAAfter, uint256 takerBalanceBAfter) = getTakerBalances(swapProgram.taker);

        uint256 baseAmountIn = Math.ceilDiv(setup.balanceA * amountOut, setup.balanceB - amountOut);
        uint256 expectedFee = Math.ceilDiv(baseAmountIn * uint256(setup.feeInBps), BPS - uint256(setup.feeInBps));
        uint256 amountInExpected = baseAmountIn + expectedFee;
        assertApproxEqAbs(takerBalanceABefore - takerBalanceAAfter, amountInExpected, 1, "Taker paid correct amountIn");
        assertEq(makerBalanceAAfter, makerBalanceABefore + amountIn, "Maker balance A should increase by amountIn");
        assertEq(makerBalanceBAfter, makerBalanceBBefore - amountOut, "Maker balance B should decrease by amountOut");
        assertEq(takerBalanceAAfter, takerBalanceABefore - amountIn, "Taker balance A should decrease by amountIn");
        assertEq(takerBalanceBAfter, takerBalanceBBefore + amountOut, "Taker balance B should increase by amountOut");
    }

    function test_Aqua_FeeIn_ExactIn_100Percent_ShouldRevert() public {
        MakerSetup memory setup = _makerSetup(1e9); // 100% fee in
        ISwapVM.Order memory order = createStrategy(setup);
        shipStrategy(order, tokenA, tokenB, setup.balanceA, setup.balanceB);
        SwapProgram memory swapProgram = _swapProgram(100e18, true, true); // Swap 100 tokenA for tokenB

        mintTokenInToTaker(swapProgram);
        mintTokenOutToMaker(swapProgram, 200e18);

        vm.expectRevert(abi.encodeWithSelector(TakerTraitsLib.TakerTraitsAmountOutMustBeGreaterThanZero.selector, 0));
        swap(swapProgram, order);
    }

    function test_Aqua_FeeIn_ExactOut_100Percent_ShouldRevert() public {
        MakerSetup memory setup = _makerSetup(1e9); // 100% fee in
        ISwapVM.Order memory order = createStrategy(setup);
        shipStrategy(order, tokenA, tokenB, setup.balanceA, setup.balanceB);
        SwapProgram memory swapProgram = _swapProgram(100e18, true, false); // Swap for 100 tokenB

        mintTokenInToTaker(swapProgram);
        mintTokenOutToMaker(swapProgram, 200e18);

        // impossible to pay 100% feeIn on exactOut swap
        vm.expectRevert();
        swap(swapProgram, order);
    }
}

project/test/FeeIndifferencyToSwap.t.sol.content:
// SPDX-License-Identifier: LicenseRef-Degensoft-SwapVM-1.1
pragma solidity ^0.8.30;

/// @custom:license-url https://github.com/1inch/swap-vm/blob/main/LICENSES/SwapVM-1.1.txt
/// @custom:copyright © 2025 Degensoft Ltd

import { Test } from "forge-std/Test.sol";

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { CalldataPtr, CalldataPtrLib } from "@1inch/solidity-utils/contracts/libraries/CalldataPtr.sol";

import { Fee, BPS } from "../src/instructions/Fee.sol";
import { FeeExperimental } from "../src/instructions/FeeExperimental.sol";
import { Context, VM, SwapQuery, SwapRegisters, ContextLib } from "../src/libs/VM.sol";

/**
 * @title UniversalFeeTest
 * @notice Proves that Fee module works independently of swap formula
 * @dev Tests FeeIn/FeeOut with different swap formulas to show consistent behavior
 */
contract FeeIndifferencyToSwap is Test, FeeExperimental {
    using ContextLib for Context;
    using CalldataPtrLib for CalldataPtr;

    uint256 constant ONE = 1e18;

    constructor() FeeExperimental(address(0)) {}

    /**
     * @notice Creates a mock Context with custom swap formula
     * @param balanceIn Initial balance of input token
     * @param balanceOut Initial balance of output token
     * @param amount Swap amount (input for exactIn, output for exactOut)
     * @param exactIn Whether this is exactIn or exactOut swap
     * @param instruction Swap instruction to use
     */
    function createContextWithSpecificInstruction(
        uint256 balanceIn,
        uint256 balanceOut,
        uint256 amount,
        bool exactIn,
        function(Context memory, bytes calldata) internal instruction
    ) internal view returns (Context memory ctx) {
        // Setup SwapRegisters
        ctx.swap.balanceIn = balanceIn;
        ctx.swap.balanceOut = balanceOut;
        ctx.swap.amountIn = exactIn ? amount : 0;
        ctx.swap.amountOut = exactIn ? 0 : amount;

        // Setup SwapQuery
        ctx.query.isExactIn = exactIn;

        // Setup VM with our custom opcodes
        ctx.vm.opcodes = new function(Context memory, bytes calldata) internal[](256);
        ctx.vm.opcodes[0] = instruction;
        ctx.vm.nextPC = 0;
        ctx.vm.isStaticContext = true;

        bytes memory programBytes = hex"0000"; // opcode 0, args length 0
        ctx.vm.programPtr = this.getProgramPtr(programBytes);
    }

    // Helper to get calldata pointer
    function getProgramPtr(bytes calldata programBytes) external pure returns (CalldataPtr ptr) {
        return CalldataPtrLib.from(programBytes);
    }

    /**
     * @notice Checks that exactIn and exactOut give consistent exchange rates
     * @param swapInstruction Swap formula to test
     * @param balanceIn Initial input token balance
     * @param balanceOut Initial output token balance
     * @param feeBps Fee in basis points
     * @param isFeeIn Whether to test feeIn (true) or feeOut (false)
     */
    function checkExactInExactOutSymmetry(
        function(Context memory, bytes calldata) internal swapInstruction,
        uint256 balanceIn,
        uint256 balanceOut,
        uint256 feeBps,
        bool isFeeIn
    ) internal {
        uint256 inputAmount = 10e18; // Use smaller amount to avoid overflow

        // Step 1: ExactIn swap
        Context memory ctxExactIn = createContextWithSpecificInstruction(
            balanceIn, balanceOut, inputAmount, true, swapInstruction
        );

        isFeeIn ? _feeAmountIn(ctxExactIn, feeBps) : _feeAmountOut(ctxExactIn, feeBps);

        // Step 2: ExactOut swap requesting the same outputAmount
        Context memory ctxExactOut = createContextWithSpecificInstruction(
            balanceIn, balanceOut, ctxExactIn.swap.amountOut, false, swapInstruction
        );

        isFeeIn ? _feeAmountIn(ctxExactOut, feeBps) : _feeAmountOut(ctxExactOut, feeBps);

        // Step 3: Verify symmetry of ExactIn and ExactOut
        // For inverse formula, we need higher tolerance due to division operations
        uint256 tolerance = (swapInstruction == inverseFormula) ? 12000 : 2;
        assertApproxEqAbs(ctxExactOut.swap.amountIn, inputAmount, tolerance, "Exchange rate inconsistent between exactIn and exactOut");
    }

    function test_FeeIn_WithXYCFormula() public {
        checkExactInExactOutSymmetry(
            xycFormula,
            100e18, // balanceIn
            200e18, // balanceOut
            0.03e9, // 3% fee
            true // isFeeIn
        );
    }

    function test_FeeIn_WithLinearFormula() public {
        checkExactInExactOutSymmetry(
            linearFormula,
            100e18, // balanceIn
            200e18, // balanceOut
            0.03e9, // 3% fee
            true // isFeeIn
        );
    }

    function test_FeeIn_WithCircularFormula() public {
        checkExactInExactOutSymmetry(
            circularFormula,
            100e18, // balanceIn
            500e18, // balanceOut
            0.03e9, // 3% fee
            true // isFeeIn
        );
    }

    function test_FeeIn_WithConstantSumFormula() public {
        checkExactInExactOutSymmetry(
            constantSumFormula,
            100e18, // balanceIn
            500e18, // balanceOut
            0.03e9, // 3% fee
            true // isFeeIn
        );
    }


    function test_FeeIn_WithSmoothTransitionFormula() public {
        checkExactInExactOutSymmetry(
            smoothTransitionFormula,
            100e18, // balanceIn
            500e18, // balanceOut (use larger pool for smooth transition)
            0.03e9, // 3% fee
            true // isFeeIn
        );
    }

    function test_FeeOut_WithXYCFormula() public {
        checkExactInExactOutSymmetry(
            xycFormula,
            100e18, // balanceIn
            200e18, // balanceOut
            0.03e9, // 3% fee
            false // isFeeIn
        );
    }

    function test_FeeOut_WithLinearFormula() public {
        checkExactInExactOutSymmetry(
            linearFormula,
            100e18, // balanceIn
            200e18, // balanceOut
            0.03e9, // 3% fee
            false // isFeeIn
        );
    }

    function test_FeeOut_WithCircularFormula() public {
        checkExactInExactOutSymmetry(
            circularFormula,
            100e18, // balanceIn
            500e18, // balanceOut
            0.03e9, // 3% fee
            false // isFeeIn
        );
    }

    function test_FeeOut_WithConstantSumFormula() public {
        checkExactInExactOutSymmetry(
            constantSumFormula,
            100e18, // balanceIn
            500e18, // balanceOut (use larger pool for constant sum)
            0.03e9, // 3% fee
            false // isFeeIn
        );
    }


    function test_FeeOut_WithSmoothTransitionFormula() public {
        checkExactInExactOutSymmetry(
            smoothTransitionFormula,
            100e18, // balanceIn
            700e18, // balanceOut (use larger pool for smooth transition)
            0.03e9, // 3% fee
            false // isFeeIn
        );
    }

    function test_FeeIn_WithInverseFormula() public {
        checkExactInExactOutSymmetry(
            inverseFormula,
            100e18, // balanceIn
            100e18, // balanceOut
            0.03e9, // 3% fee
            true // isFeeIn
        );
    }

    function test_FeeOut_WithInverseFormula() public {
        checkExactInExactOutSymmetry(
            inverseFormula,
            100e18, // balanceIn
            300e18, // balanceOut
            0.03e9, // 3% fee
            false // isFeeOut
        );
    }

    function test_FeeIn_WithHyperbolicFormula() public {
        checkExactInExactOutSymmetry(
            hyperbolicFormula,
            100e18, // balanceIn
            100e18, // balanceOut
            0.03e9, // 3% fee
            true // isFeeIn
        );
    }

    function test_FeeOut_WithHyperbolicFormula() public {
        checkExactInExactOutSymmetry(
            hyperbolicFormula,
            100e18, // balanceIn
            100e18, // balanceOut
            0.03e9, // 3% fee
            false // isFeeOut
        );
    }

    // === SWAP FORMULAS ===

    /**
     * @notice Standard XYC formula: x * y = k
     */
    function xycFormula(Context memory ctx, bytes calldata) internal pure {
        if (ctx.query.isExactIn) {
            require(ctx.swap.amountOut == 0, "XYC: amountOut should be 0 for exactIn");
            ctx.swap.amountOut = (ctx.swap.amountIn * ctx.swap.balanceOut) /
                                (ctx.swap.balanceIn + ctx.swap.amountIn);
        } else {
            require(ctx.swap.amountIn == 0, "XYC: amountIn should be 0 for exactOut");
            ctx.swap.amountIn = Math.ceilDiv(
                ctx.swap.amountOut * ctx.swap.balanceIn,
                ctx.swap.balanceOut - ctx.swap.amountOut
            );
        }
    }

    /**
     * @notice Linear formula: fixed exchange rate
     * @dev Uses rate of balanceOut/balanceIn as price
     */
    function linearFormula(Context memory ctx, bytes calldata) internal pure {
        uint256 price = ctx.swap.balanceOut * ONE / ctx.swap.balanceIn; // price in 1e18 precision

        if (ctx.query.isExactIn) {
            require(ctx.swap.amountOut == 0, "Linear: amountOut should be 0 for exactIn");
            ctx.swap.amountOut = ctx.swap.amountIn * price / ONE;
        } else {
            require(ctx.swap.amountIn == 0, "Linear: amountIn should be 0 for exactOut");
            ctx.swap.amountIn = Math.ceilDiv(ctx.swap.amountOut * ONE, price);
        }
    }

    /**
     * @notice Circular formula: x² + y² = k²
     * @dev Non-linear formula that maintains circular invariant
     */
    function circularFormula(Context memory ctx, bytes calldata) internal pure {
        uint256 k2 = ctx.swap.balanceIn * ctx.swap.balanceIn +
                     ctx.swap.balanceOut * ctx.swap.balanceOut;

        if (ctx.query.isExactIn) {
            require(ctx.swap.amountOut == 0, "Circular: amountOut should be 0 for exactIn");
            uint256 newBalanceIn = ctx.swap.balanceIn + ctx.swap.amountIn;
            require(newBalanceIn * newBalanceIn < k2, "Circular: Would exceed invariant");
            ctx.swap.amountOut = ctx.swap.balanceOut - Math.sqrt(k2 - newBalanceIn * newBalanceIn);
        } else {
            require(ctx.swap.amountIn == 0, "Circular: amountIn should be 0 for exactOut");
            uint256 newBalanceOut = ctx.swap.balanceOut - ctx.swap.amountOut;
            require(newBalanceOut * newBalanceOut < k2, "Circular: Would exceed invariant");
            ctx.swap.amountIn = Math.sqrt(k2 - newBalanceOut * newBalanceOut) - ctx.swap.balanceIn;
        }
    }

    /**
     * @notice Constant sum formula: x + y = k
     */
    function constantSumFormula(Context memory ctx, bytes calldata) internal pure {
        // For constant sum, the exchange rate is always 1:1
        if (ctx.query.isExactIn) {
            require(ctx.swap.amountOut == 0, "ConstantSum: amountOut should be 0 for exactIn");
            ctx.swap.amountOut = ctx.swap.amountIn;
            require(ctx.swap.amountOut <= ctx.swap.balanceOut, "ConstantSum: Insufficient balanceOut");
        } else {
            require(ctx.swap.amountIn == 0, "ConstantSum: amountIn should be 0 for exactOut");
            ctx.swap.amountIn = ctx.swap.amountOut;
        }
    }


    /**
     * @notice Harmonic mean style formula: 2xy/(x+y) = k
     */
    function smoothTransitionFormula(Context memory ctx, bytes calldata) internal pure {
        // k = 2 * balanceIn * balanceOut / (balanceIn + balanceOut)
        uint256 k = 2 * ctx.swap.balanceIn * ctx.swap.balanceOut / (ctx.swap.balanceIn + ctx.swap.balanceOut);

        if (ctx.query.isExactIn) {
            require(ctx.swap.amountOut == 0, "SmoothTransition: amountOut should be 0 for exactIn");
            uint256 newBalanceIn = ctx.swap.balanceIn + ctx.swap.amountIn;

            // Solve for newBalanceOut: 2 * newBalanceIn * newBalanceOut / (newBalanceIn + newBalanceOut) = k
            // This gives: newBalanceOut = k * newBalanceIn / (2 * newBalanceIn - k)
            uint256 newBalanceOut = k * newBalanceIn / (2 * newBalanceIn - k);
            ctx.swap.amountOut = ctx.swap.balanceOut - newBalanceOut;
        } else {
            require(ctx.swap.amountIn == 0, "SmoothTransition: amountIn should be 0 for exactOut");
            uint256 newBalanceOut = ctx.swap.balanceOut - ctx.swap.amountOut;

            // Solve for newBalanceIn: 2 * newBalanceIn * newBalanceOut / (newBalanceIn + newBalanceOut) = k
            // This gives: newBalanceIn = k * newBalanceOut / (2 * newBalanceOut - k)
            uint256 newBalanceIn = Math.ceilDiv(k * newBalanceOut, 2 * newBalanceOut - k);
            ctx.swap.amountIn = newBalanceIn - ctx.swap.balanceIn;
        }
    }

    /**
     * @notice Inverse formula: 1/x + 1/y = k
     */
    function inverseFormula(Context memory ctx, bytes calldata) internal pure {
        // k = 1/balanceIn + 1/balanceOut
        uint256 k = (ONE * ctx.swap.balanceOut + ONE * ctx.swap.balanceIn) * ONE / (ctx.swap.balanceIn * ctx.swap.balanceOut);

        if (ctx.query.isExactIn) {
            require(ctx.swap.amountOut == 0, "Inverse: amountOut should be 0 for exactIn");
            uint256 newBalanceIn = ctx.swap.balanceIn + ctx.swap.amountIn;

            // 1/newBalanceIn + 1/newBalanceOut = k
            // 1/newBalanceOut = k - 1/newBalanceIn
            // newBalanceOut = 1 / (k - 1/newBalanceIn)
            uint256 newInverseOut = k - ONE * ONE / newBalanceIn;
            require(newInverseOut > 0, "Inverse: Would result in negative balance");
            uint256 newBalanceOut = ONE * ONE / newInverseOut;
            ctx.swap.amountOut = ctx.swap.balanceOut - newBalanceOut;
        } else {
            require(ctx.swap.amountIn == 0, "Inverse: amountIn should be 0 for exactOut");
            uint256 newBalanceOut = ctx.swap.balanceOut - ctx.swap.amountOut;

            // 1/newBalanceIn + 1/newBalanceOut = k
            // 1/newBalanceIn = k - 1/newBalanceOut
            // newBalanceIn = 1 / (k - 1/newBalanceOut)
            uint256 newInverseIn = k - ONE * ONE / newBalanceOut;
            require(newInverseIn > 0, "Inverse: Would result in negative balance");
            uint256 newBalanceIn = Math.ceilDiv(ONE * ONE, newInverseIn);
            ctx.swap.amountIn = newBalanceIn - ctx.swap.balanceIn;
        }
    }

    /**
     * @notice Hyperbolic formula: x/y + y/x = k
     * @dev For balanced pools where x=y, k=2. This is a special case that simplifies calculations.
     */
    function hyperbolicFormula(Context memory ctx, bytes calldata) internal pure {
        // For simplicity and to avoid overflow, we'll implement this for balanced pools only
        // where balanceIn = balanceOut, which gives us k = 2
        require(ctx.swap.balanceIn == ctx.swap.balanceOut, "Hyperbolic: Only balanced pools supported");

        if (ctx.query.isExactIn) {
            require(ctx.swap.amountOut == 0, "Hyperbolic: amountOut should be 0 for exactIn");

            // For this simplified hyperbolic formula, we'll use a modified constant product approach
            // that maintains the spirit of x/y + y/x = k but ensures valid swaps
            // We'll use: amountOut = amountIn * balance / (balance + 2*amountIn)
            // This gives diminishing returns as trade size increases

            uint256 balance = ctx.swap.balanceIn; // Same as balanceOut for balanced pools
            ctx.swap.amountOut = ctx.swap.amountIn * balance / (balance + 2 * ctx.swap.amountIn);
        } else {
            require(ctx.swap.amountIn == 0, "Hyperbolic: amountIn should be 0 for exactOut");

            // For exactOut: amountIn = amountOut * balance / (balance - 2*amountOut)
            uint256 balance = ctx.swap.balanceOut; // Same as balanceIn for balanced pools
            require(2 * ctx.swap.amountOut < balance, "Hyperbolic: Amount too large");

            ctx.swap.amountIn = Math.ceilDiv(
                ctx.swap.amountOut * balance,
                balance - 2 * ctx.swap.amountOut
            );
        }
    }
}

project/test/FeeOutAdditivityViolation.t.content:
// SPDX-License-Identifier: LicenseRef-Degensoft-SwapVM-1.1
pragma solidity ^0.8.30;

/// @custom:license-url https://github.com/1inch/swap-vm/blob/main/LICENSES/SwapVM-1.1.txt
/// @custom:copyright © 2025 Degensoft Ltd

import { Test } from "forge-std/Test.sol";
import { console2 as console } from "forge-std/console2.sol";
import { TokenMock } from "@1inch/solidity-utils/contracts/mocks/TokenMock.sol";

import { Aqua } from "@1inch/aqua/src/Aqua.sol";

import { ISwapVM } from "../src/interfaces/ISwapVM.sol";
import { SwapVM } from "../src/SwapVM.sol";
import { SwapVMRouter } from "../src/routers/SwapVMRouter.sol";
import { MakerTraitsLib } from "../src/libs/MakerTraits.sol";
import { TakerTraitsLib } from "../src/libs/TakerTraits.sol";
import { OpcodesDebug } from "../src/opcodes/OpcodesDebug.sol";
import { Program, ProgramBuilder } from "./utils/ProgramBuilder.sol";
import { BalancesArgsBuilder } from "../src/instructions/Balances.sol";
import { FeeArgsBuilder } from "../src/instructions/Fee.sol";
import { dynamic } from "./utils/Dynamic.sol";

/**
 * @title FeeOutAdditivityViolation
 * @notice Tests demonstrating that feeOut violates additivity and when splitting is profitable
 * @dev Shows:
 *   1. Original _flatFeeAmountOutXD violates additivity
 *   2. _feeOutAsInXYCXD also violates additivity (due to variable feeInBps)
 *   3. When splitting swaps is profitable considering gas costs
 */
contract FeeOutAdditivityViolation is Test, OpcodesDebug {
    using ProgramBuilder for Program;

    Aqua public immutable aqua;
    SwapVMRouter public swapVM;
    TokenMock public tokenA;
    TokenMock public tokenB;

    address public maker;
    uint256 public makerPK = 0x1234;
    address public taker;

    uint256 constant BALANCE = 1000e18;
    uint32 constant FEE_BPS = 0.005e9; // 0.5% fee

    // Base tx cost (always 21000)
    uint256 constant BASE_TX_COST = 21_000;

    constructor() OpcodesDebug(address(aqua = new Aqua())) {}

    function setUp() public {
        maker = vm.addr(makerPK);
        taker = address(this);
        swapVM = new SwapVMRouter(address(aqua), address(0), address(this), "SwapVM", "1.0.0");

        tokenA = new TokenMock("Token A", "TKA");
        tokenB = new TokenMock("Token B", "TKB");

        // Setup tokens and approvals for maker
        tokenA.mint(maker, 100000e18);
        tokenB.mint(maker, 100000e18);
        vm.prank(maker);
        tokenA.approve(address(swapVM), type(uint256).max);
        vm.prank(maker);
        tokenB.approve(address(swapVM), type(uint256).max);

        // Setup approvals for taker (test contract)
        tokenA.mint(taker, 100000e18);
        tokenA.approve(address(swapVM), type(uint256).max);
        tokenB.approve(address(swapVM), type(uint256).max);
    }

    /**
     * @notice Test showing original _flatFeeAmountOutXD violates additivity
     * @dev Split swaps get MORE output than single swap (fee "reinvested" in balanceOut)
     */
    function test_FlatFeeOut_Original_ViolatesAdditivity() public {
        console.log("=== Original _flatFeeAmountOutXD Additivity Test ===");
        console.log("Parameters: Balance = 1000 tokens, Fee = 0.5%");

        ISwapVM.Order memory order = _createOrderWithFlatFeeOut();
        bytes memory takerData = _signAndPackTakerData(order, true, 0);

        uint256 swapAmount = 100e18;

        // Single swap: swap(100)
        (uint256 singleIn, uint256 singleOut) = _quoteSwap(order, swapAmount, takerData);
        console.log("Single swap(100):");
        console.log("  amountIn (wei):", singleIn);
        console.log("  amountOut (wei):", singleOut);

        // Split swap: swap(50) + swap(50)
        // Need to execute first swap to change state, then quote second
        uint256 halfAmount = swapAmount / 2;

        // Execute first swap
        _executeSwap(order, halfAmount, takerData);
        (uint256 split1In, uint256 split1Out) = (halfAmount, _getLastSwapOut());

        // Quote second swap (state changed)
        (uint256 split2In, uint256 split2Out) = _quoteSwap(order, halfAmount, takerData);

        uint256 splitTotalOut = split1Out + split2Out;

        console.log("Split swap(50) + swap(50):");
        console.log("  First out:", split1Out);
        console.log("  Second out:", split2Out);
        console.log("  Total out:", splitTotalOut);

        // Check additivity violation
        if (splitTotalOut > singleOut) {
            uint256 profit = splitTotalOut - singleOut;
            console.log("!!! ADDITIVITY VIOLATED !!! Split > Single");
            console.log("Profit from splitting (wei):", profit);

            // This should fail - additivity is violated
            assertGt(splitTotalOut, singleOut, "Split should get more than single (additivity violated)");
        } else {
            console.log("Additivity preserved (single >= split)");
        }
    }

    /**
     * @notice Test calculating when splitting is profitable considering gas costs
     * @dev Uses same order and compares quote(100) vs execute(50)+quote(50)
     */
    function test_FeeOut_SplitProfitability() public {
        console.log("=== Split Profitability Analysis ===");
        console.log("Balance = 1000 tokens, Fee = 0.5%");

        uint256 swapAmount = 100e18;

        // Extra gas for additional tx: base + calldata
        uint256 extraTxGas = BASE_TX_COST + (800 * 16); // ~33,800 gas

        // Create one order for comparison
        ISwapVM.Order memory order = _createOrderWithFlatFeeOut();
        bytes memory takerData = _signAndPackTakerData(order, true, 0);

        // === Single swap: quote(100) ===
        (, uint256 singleOut) = _quoteSwap(order, swapAmount, takerData);
        console.log("Single swap(100) amountOut:", singleOut);

        // === Split swap: execute(50) + quote(50) on same order ===
        uint256 gasBefore = gasleft();
        _executeSwap(order, swapAmount / 2, takerData);
        uint256 split1ExecGas = gasBefore - gasleft();
        uint256 split1Out = _getLastSwapOut();

        (, uint256 split2Out) = _quoteSwap(order, swapAmount / 2, takerData);

        uint256 splitTotalOut = split1Out + split2Out;

        console.log("Split swap(50+50):");
        console.log("  First out:", split1Out);
        console.log("  Second out:", split2Out);
        console.log("  Total out:", splitTotalOut);

        // === Profitability Analysis ===
        console.log("=== Profitability Analysis ===");

        if (splitTotalOut > singleOut) {
            uint256 profitTokens = splitTotalOut - singleOut;
            console.log("Profit from splitting (wei):", profitTokens);

            // Extra gas for second tx = BASE_TX_COST + calldata + execution
            // Execution gas is roughly same as first split (~65k)
            uint256 extraGas = extraTxGas + split1ExecGas;
            console.log("Extra gas for split:", extraGas);

            uint256[4] memory gasPrices = [uint256(10), 30, 100, 300];

            for (uint256 j = 0; j < 4; j++) {
                uint256 gasCostWei = extraGas * gasPrices[j] * 1e9;
                console.log("At", gasPrices[j], "gwei:");
                console.log("  Extra gas cost (ETH wei):", gasCostWei);

                // Assuming 1 token ≈ 1 ETH for comparison
                if (profitTokens > gasCostWei) {
                    console.log("  -> PROFITABLE! Net (if token~=ETH):", profitTokens - gasCostWei);
                } else {
                    console.log("  -> NOT profitable (if token~=ETH), loss:", gasCostWei - profitTokens);
                }
            }

            // Breakeven gas price
            uint256 breakevenGwei = profitTokens / extraGas / 1e9;
            console.log("Breakeven gas price:", breakevenGwei, "gwei (if token~=ETH)");

            // Assert that additivity is violated
            assertGt(splitTotalOut, singleOut, "FeeOut should violate additivity");
        } else {
            console.log("No profit from splitting - single >= split");
        }
    }

    /**
     * @notice Binary search to find minimum swap size where splitting is profitable
     * @dev For each gas price, find the minimum swap amount where profit > gas cost
     */
    function test_FeeOut_MinProfitableSwapSize() public {
        console.log("=== Minimum Profitable Swap Size (Binary Search) ===");
        console.log("Balance = 1000 tokens, Fee = 0.5%");

        // Extra gas for additional tx
        uint256 extraTxGas = BASE_TX_COST + (800 * 16) + 165_000; // base + calldata + exec ≈ 200k

        uint256[4] memory gasPrices = [uint256(10), 30, 100, 300];

        for (uint256 i = 0; i < gasPrices.length; i++) {
            uint256 gasPrice = gasPrices[i];
            uint256 gasCostWei = extraTxGas * gasPrice * 1e9;

            console.log("--- Gas price:", gasPrice, "gwei ---");
            console.log("Gas cost (wei):", gasCostWei);

            // Binary search for minimum profitable swap size
            uint256 low = 1e18;      // 1 token
            uint256 high = BALANCE;  // 1000 tokens
            uint256 minProfitable = 0;

            while (low <= high) {
                uint256 mid = (low + high) / 2;

                uint256 profit = _calculateSplitProfit(mid);

                if (profit > gasCostWei) {
                    minProfitable = mid;
                    high = mid - 1e17; // Decrease by 0.1 token
                } else {
                    low = mid + 1e17;  // Increase by 0.1 token
                }

                // Prevent infinite loop
                if (high < low || (high - low < 1e17)) break;
            }

            if (minProfitable > 0) {
                uint256 profitAtMin = _calculateSplitProfit(minProfitable);
                console.log("Min profitable swap (tokens):", minProfitable / 1e18);
                console.log("Profit at min (wei):", profitAtMin);
                console.log("Net profit (wei):", profitAtMin - gasCostWei);
            } else {
                console.log("No profitable swap size found (need > 1000 tokens)");
            }
        }
    }

    /**
     * @notice Calculate profit from splitting a swap using pure math
     */
    function _calculateSplitProfit(uint256 swapAmount) private returns (uint256) {
        ISwapVM.Order memory order = _createOrderWithFlatFeeOut();
        bytes memory takerData = _signAndPackTakerData(order, true, 0);

        // Save the current state
        uint256 snapshot = vm.snapshot();

        // Single swap
        (, uint256 singleOut) = _quoteSwap(order, swapAmount, takerData);

        // Restore state to before the swap
        vm.revertTo(snapshot);

        // Split swap - simulate by calculating XYC formula
        // First half
        uint256 half = swapAmount / 2;

        // Save the current state
        snapshot = vm.snapshot();
        (, uint256 split1Out) = _quoteSwap(order, half, takerData);
        (, uint256 split2Out) = _quoteSwap(order, half, takerData);
        // Restore state to before the swap
        vm.revertTo(snapshot);

        uint256 splitTotal = split1Out + split2Out;

        if (splitTotal > singleOut) {
            return splitTotal - singleOut;
        }
        return 0;
    }

    /**
     * @notice Compare feeIn vs feeOut additivity
     * @dev Shows that feeIn preserves additivity while feeOut violates it
     */
    function test_FeeIn_vs_FeeOut_Additivity() public {
        console.log("=== FeeIn vs FeeOut Additivity Comparison ===");

        uint256 swapAmount = 100e18;

        // Test FeeIn
        console.log("\n--- FeeIn (_flatFeeAmountInXD) ---");
        {
            ISwapVM.Order memory order = _createOrderWithFlatFeeIn();
            bytes memory takerData = _signAndPackTakerData(order, true, 0);

            (,uint256 singleOut) = _quoteSwap(order, swapAmount, takerData);

            _executeSwap(order, swapAmount / 2, takerData);
            uint256 split1Out = _getLastSwapOut();
            (,uint256 split2Out) = _quoteSwap(order, swapAmount / 2, takerData);

            uint256 splitTotalOut = split1Out + split2Out;

            console.log("Single out:", singleOut);
            console.log("Split out:", splitTotalOut);

            if (singleOut >= splitTotalOut) {
                console.log("-> Additivity PRESERVED");
            } else {
                console.log("-> VIOLATED! Diff:", splitTotalOut - singleOut);
            }
        }

        // Test FeeOut
        console.log("--- FeeOut (_flatFeeAmountOutXD) ---");
        {
            ISwapVM.Order memory order = _createOrderWithFlatFeeOut();
            bytes memory takerData = _signAndPackTakerData(order, true, 0);

            (,uint256 singleOut) = _quoteSwap(order, swapAmount, takerData);

            _executeSwap(order, swapAmount / 2, takerData);
            uint256 split1Out = _getLastSwapOut();
            (,uint256 split2Out) = _quoteSwap(order, swapAmount / 2, takerData);

            uint256 splitTotalOut = split1Out + split2Out;

            console.log("Single out:", singleOut);
            console.log("Split out:", splitTotalOut);

            if (singleOut >= splitTotalOut) {
                console.log("-> Additivity PRESERVED");
            } else {
                console.log("-> VIOLATED! Diff:", splitTotalOut - singleOut);
            }
        }
    }

    // ==================== Helper Functions ====================

    uint256 private _lastSwapOut;

    function _getLastSwapOut() private view returns (uint256) {
        return _lastSwapOut;
    }

    function _createOrderWithFlatFeeOut() private view returns (ISwapVM.Order memory) {
        Program memory program = ProgramBuilder.init(_opcodes());
        bytes memory bytecode = bytes.concat(
            program.build(_dynamicBalancesXD,
                BalancesArgsBuilder.build(
                    dynamic([address(tokenA), address(tokenB)]),
                    dynamic([BALANCE, BALANCE])
                )),
            program.build(_flatFeeAmountOutXD, FeeArgsBuilder.buildFlatFee(FEE_BPS)),
            program.build(_xycSwapXD)
        );
        return _createOrder(bytecode);
    }

    function _createOrderWithFlatFeeIn() private view returns (ISwapVM.Order memory) {
        Program memory program = ProgramBuilder.init(_opcodes());
        bytes memory bytecode = bytes.concat(
            program.build(_dynamicBalancesXD,
                BalancesArgsBuilder.build(
                    dynamic([address(tokenA), address(tokenB)]),
                    dynamic([BALANCE, BALANCE])
                )),
            program.build(_flatFeeAmountInXD, FeeArgsBuilder.buildFlatFee(FEE_BPS)),
            program.build(_xycSwapXD)
        );
        return _createOrder(bytecode);
    }

    function _createOrder(bytes memory program) private view returns (ISwapVM.Order memory) {
        return MakerTraitsLib.build(MakerTraitsLib.Args({
            maker: maker,
            shouldUnwrapWeth: false,
            useAquaInsteadOfSignature: false,
            allowZeroAmountIn: false,
            receiver: address(0),
            hasPreTransferInHook: false,
            hasPostTransferInHook: false,
            hasPreTransferOutHook: false,
            hasPostTransferOutHook: false,
            preTransferInTarget: address(0),
            preTransferInData: "",
            postTransferInTarget: address(0),
            postTransferInData: "",
            preTransferOutTarget: address(0),
            preTransferOutData: "",
            postTransferOutTarget: address(0),
            postTransferOutData: "",
            program: program
        }));
    }

    function _signAndPackTakerData(
        ISwapVM.Order memory order,
        bool isExactIn,
        uint256 threshold
    ) private view returns (bytes memory) {
        bytes32 orderHash = swapVM.hash(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerPK, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        bytes memory thresholdData = threshold > 0 ? abi.encodePacked(bytes32(threshold)) : bytes("");

        bytes memory takerTraits = TakerTraitsLib.build(TakerTraitsLib.Args({
            taker: address(0),
            isExactIn: isExactIn,
            shouldUnwrapWeth: false,
            isStrictThresholdAmount: false,
            isFirstTransferFromTaker: false,
            useTransferFromAndAquaPush: false,
            threshold: thresholdData,
            to: address(this),
            deadline: 0,
            hasPreTransferInCallback: false,
            hasPreTransferOutCallback: false,
            preTransferInHookData: "",
            postTransferInHookData: "",
            preTransferOutHookData: "",
            postTransferOutHookData: "",
            preTransferInCallbackData: "",
            preTransferOutCallbackData: "",
            instructionsArgs: "",
            signature: signature
        }));

        return abi.encodePacked(takerTraits);
    }

    function _quoteSwap(
        ISwapVM.Order memory order,
        uint256 amount,
        bytes memory takerData
    ) private view returns (uint256 amountIn, uint256 amountOut) {
        (amountIn, amountOut,) = swapVM.asView().quote(
            order,
            address(tokenA),
            address(tokenB),
            amount,
            takerData
        );
    }

    function _executeSwap(
        ISwapVM.Order memory order,
        uint256 amount,
        bytes memory takerData
    ) private {
        (,uint256 amountOut,) = swapVM.swap(
            order,
            address(tokenA),
            address(tokenB),
            amount,
            takerData
        );
        _lastSwapOut = amountOut;
    }
}

